I noticed that (sub)agent permissions get merged with top-level permissions, so if you do not specify any top-level permissions your sub-agent permissions inherit `"tool": "allow"` from the default top-level which has "allow" for almost every tool. I solved it by making top-level permissions "read-only" and giving edit (and other destructive permissions) for every (sub)agent separately, like this:

```jsonc
{
  "$schema": "https://opencode.ai/config.json",
  // set readonly global permissions, it will override default permissions for all agents, including the built-in agents (build, general, explore...)
  "permission": {
    "*": "ask",
    "read": {
      "*": "allow",
      "*.env": "deny",
      "*.env.*": "deny",
      "*.env.example": "allow"
    },
    "edit": "ask",
    "task": {
      // do not allow running subagents with edit permissions by default without user confirmation
      "*": "ask",
      "explore": "allow",
    },
  },
  "agent": {
    // allow edit permissions for specific agents
    "build": {
      "permission": {
        "edit": {
          "*": "allow",
        },
        "task": {
          // allow agents with edit permission to run subagents with edit permissions by default without user confirmation
          "general": "allow",
        },
      },
    },
    "general": {
      "permission": {
        "edit": {
          "*": "allow",
        },
        "task": {
          "general": "allow",
        },
      },
    },
  },
}
```

