  "diff_style": "auto",
  "keybindings": [
    {
      "keys": "shift+enter",
      "id": "User.sendInput.ShiftEnterNewline"
    }
  ],
  "actions": [
    {
      "id": "User.sendInput.ShiftEnterNewline",
